    }

    function run(uint256 amount, address other) public {
        require(other != address(0));

        uint256 supplyBefore = c.totalSupply();
        uint256 ownerBalBefore = c.balanceOf(address(this));
        uint256 otherBalBefore = c.balanceOf(other);
        require(ownerBalBefore >= amount);

        bool reverted;
        try c.burn(amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 ownerBalAfter = c.balanceOf(address(this));
        uint256 otherBalAfter = c.balanceOf(other);
        assert(!reverted && ownerBalAfter == ownerBalBefore - amount && otherBalAfter == otherBalBefore);
    }
